import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.vLhlLNVn.js";const k=JSON.parse('{"title":"CLI Tools Reference","description":"Reference for the console jetpack developer CLI (init, mcp, codegen, validate, install-local, package) and jetpack-daemon runtime/signing flags.","frontmatter":{"description":"Reference for the console jetpack developer CLI (init, mcp, codegen, validate, install-local, package) and jetpack-daemon runtime/signing flags."},"headers":[],"relativePath":"publishing/cli-tools.md","filePath":"publishing/cli-tools.md","lastUpdated":1795533333000}'),i={name:"publishing/cli-tools.md"};function s(c,e,l,n,r,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="cli-tools-reference" tabindex="-1">CLI Tools Reference <a class="header-anchor" href="#cli-tools-reference" aria-label="Permalink to &quot;CLI Tools Reference&quot;">​</a></h1><p>JetPack provides two complementary binaries, both built together by <code>make release-daemon</code> and included in every release bundle (<code>JetPack.app/Contents/MacOS/</code> on macOS, <code>JetPack-windows-x64.zip</code> on Windows, and <code>JetPack-linux-x64.tar.gz</code> on Linux):</p><ul><li><strong><code>jetpack</code></strong> (<code>crates/jetpack-cli</code>) — Standalone console developer CLI for scaffolding AI-ready projects, running the local MCP server (<code>stdio</code>), generating TypeScript opcode contracts, validating manifests, and driving local installs/packaging.</li><li><strong><code>jetpack-daemon</code></strong> (<code>crates/jetpack-daemon</code>) — Native system-tray orchestrator and catalog operator binary.</li></ul><h2 id="console-developer-cli-jetpack" tabindex="-1">Console Developer CLI (<code>jetpack</code>) <a class="header-anchor" href="#console-developer-cli-jetpack" aria-label="Permalink to &quot;Console Developer CLI (`jetpack`)&quot;">​</a></h2><h3 id="jetpack-init-target-dir-app-id-id-template-python-fullstack" tabindex="-1"><code>jetpack init &lt;target_dir&gt; [--app-id &lt;id&gt;] [--template &lt;python|fullstack&gt;]</code> <a class="header-anchor" href="#jetpack-init-target-dir-app-id-id-template-python-fullstack" aria-label="Permalink to &quot;`jetpack init &lt;target_dir&gt; [--app-id &lt;id&gt;] [--template &lt;python|fullstack&gt;]`&quot;">​</a></h3><p>Scaffolds a ready-to-run JetPack project in <code>&lt;target_dir&gt;</code> with AI instructions (<code>AGENTS.md</code>, regular-file mirror <code>CLAUDE.md</code>, <code>.cursor/rules/jetpack.mdc</code>) and Agent Skills (<code>.agents/skills/create-jetpack-worker/SKILL.md</code>, <code>.agents/skills/add-binary-opcode/SKILL.md</code>, <code>.agents/skills/debug-pairing/SKILL.md</code>). Refuses to overwrite an existing <code>app.toml</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Python worker starter (default)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Fullstack TypeScript (@jetpack/client) + Python worker starter</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./apps/my-ai-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.dev.my-ai-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fullstack</span></span></code></pre></div><h3 id="jetpack-mcp" tabindex="-1"><code>jetpack mcp</code> <a class="header-anchor" href="#jetpack-mcp" aria-label="Permalink to &quot;`jetpack mcp`&quot;">​</a></h3><p>Starts the local Model Context Protocol (MCP) server (<code>rmcp</code>) over <code>stdio</code> transport (<code>stdin</code>/<code>stdout</code> JSON-RPC, all <code>tracing</code> diagnostics directed to <code>stderr</code>). Bridges AI coding agents with embedded/local documentation (<code>JETPACK_DOCS_DIR</code> override supported) and token-authenticated <code>jetpack-daemon</code> introspection (<code>pairing.ipc</code>).</p><p>Exposes 5 tools:</p><ul><li><code>search_docs(query, max_results?)</code> — Searches embedded/local JetPack SDK, security, and <code>app.toml</code> docs.</li><li><code>get_daemon_status()</code> — Checks daemon health, version, <code>127.0.0.1</code> WebSocket reachability, paired origins, and running workers.</li><li><code>read_worker_logs(app_id, lines?)</code> — Tails live or offline <code>worker.log</code> / <code>daemon.log</code> lines and crash tracebacks with sensitive token/key redaction.</li><li><code>validate_manifest(path)</code> — Validates <code>app.toml</code> against the current <code>AppManifest</code> schema.</li><li><code>scaffold_app(target_dir, app_id?, template?)</code> — Scaffolds a <code>python</code> or <code>fullstack</code> project with AI rules and Agent Skills.</li></ul><h3 id="jetpack-codegen-worker-path-out-path-strict" tabindex="-1"><code>jetpack codegen [--worker &lt;path&gt;] [--out &lt;path&gt;] [--strict]</code> <a class="header-anchor" href="#jetpack-codegen-worker-path-out-path-strict" aria-label="Permalink to &quot;`jetpack codegen [--worker &lt;path&gt;] [--out &lt;path&gt;] [--strict]`&quot;">​</a></h3><p>Parses Python worker source files or directories in pure Rust (<code>rustpython-parser</code>, zero Python runtime required) to extract Pydantic <code>BaseModel</code>, <code>TypedDict</code>, <code>@dataclass</code>, <code>@opcode(...)</code> / <code>client.opcode(...)</code> handlers, and <code>if opcode == ...</code> / <code>match</code> branches into a strict TypeScript declaration file (<code>jetpack-env.d.ts</code> exporting <code>JetPackOpcodeMap</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --worker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worker.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/jetpack-env.d.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strict</span></span></code></pre></div><ul><li><code>--worker &lt;path&gt;</code>: Python file or directory to inspect (defaults to <code>worker.py</code>).</li><li><code>--out &lt;path&gt;</code>: Output TypeScript <code>.d.ts</code> file path (defaults to <code>jetpack-env.d.ts</code>).</li><li><code>--strict</code>: Exit non-zero if zero opcodes are discovered.</li></ul><h3 id="jetpack-validate-path" tabindex="-1"><code>jetpack validate [path]</code> <a class="header-anchor" href="#jetpack-validate-path" aria-label="Permalink to &quot;`jetpack validate [path]`&quot;">​</a></h3><p>Validates <code>app.toml</code> (defaults to <code>app.toml</code> in the current directory, or <code>&lt;dir&gt;/app.toml</code> when a directory path is passed) using <code>#[serde(deny_unknown_fields)]</code> and semantic security checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker/app.toml</span></span></code></pre></div><h3 id="jetpack-install-local-path" tabindex="-1"><code>jetpack install-local</code> (<code>path</code>) <a class="header-anchor" href="#jetpack-install-local-path" aria-label="Permalink to &quot;`jetpack install-local` (`path`)&quot;">​</a></h3><p>Delegates to <code>jetpack-daemon --install-local-app &lt;path&gt;</code> to package and install a local developer worker (including any built <code>ui/</code> static directory) directly into <code>&lt;root&gt;/blobs/sha256/</code> and <code>&lt;root&gt;/apps/&lt;app-id&gt;/&lt;version&gt;/</code> in unverified developer mode (<code>is_verified = false</code>, restricted to <code>127.0.0.1</code> / <code>localhost</code>). Defaults <code>path</code> to <code>.</code>.</p><h3 id="jetpack-package-path-out-bundle-dir-oci-ref-ref" tabindex="-1"><code>jetpack package</code> (<code>path --out &lt;bundle_dir&gt; --oci-ref &lt;ref&gt;</code>) <a class="header-anchor" href="#jetpack-package-path-out-bundle-dir-oci-ref-ref" aria-label="Permalink to &quot;`jetpack package` (`path --out &lt;bundle_dir&gt; --oci-ref &lt;ref&gt;`)&quot;">​</a></h3><p>Delegates to <code>jetpack-daemon --package-app</code> to package a validated project—alongside its built <code>ui/</code> static frontend (<code>ui/index.html</code>, <code>ui/assets/*</code>) if present—into an OCI Image Layout v1.0.0 bundle (automatically excluding <code>AGENTS.md</code>, <code>CLAUDE.md</code>, <code>.cursor/</code>, <code>.agents/</code>, <code>jetpack-env.d.ts</code>, <code>node_modules/</code>, <code>target/</code>, <code>.git/</code>, <code>.venv/</code>, <code>__pycache__/</code>, symlinks, and secret files). Defaults <code>path</code> to <code>.</code>.</p><hr><h2 id="daemon-developer-publisher-flags-jetpack-daemon" tabindex="-1">Daemon Developer &amp; Publisher Flags (<code>jetpack-daemon</code>) <a class="header-anchor" href="#daemon-developer-publisher-flags-jetpack-daemon" aria-label="Permalink to &quot;Daemon Developer &amp; Publisher Flags (`jetpack-daemon`)&quot;">​</a></h2><h3 id="init-app-target-dir" tabindex="-1"><code>--init-app &lt;target_dir&gt;</code> <a class="header-anchor" href="#init-app-target-dir" aria-label="Permalink to &quot;`--init-app &lt;target_dir&gt;`&quot;">​</a></h3><p>Scaffolds a ready-to-run starter Python worker project in <code>&lt;target_dir&gt;</code> using the same shared template builder as <code>jetpack init</code> (including <code>AGENTS.md</code>, <code>CLAUDE.md</code>, <code>.cursor/rules/jetpack.mdc</code>, and <code>.agents/skills/</code>, and refusing to overwrite an existing <code>app.toml</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span></span></code></pre></div><p>Creates:</p><ul><li><code>app.toml</code> — Validated starter manifest using a non-official <code>com.dev.&lt;slug&gt;</code> ID (<code>com.dev.my-ocr-worker</code>).</li><li><code>worker.py</code> — Executable (<code>0755</code> on Unix) Python worker using <code>jetpack_sdk.JetPackClient</code>.</li><li><code>pyproject.toml</code> — Project metadata (<code>requires-python = &quot;&gt;=3.12&quot;</code>, <code>jetpack-sdk</code> dependency).</li><li><code>README.md</code> — Project-specific validation, local install, and packaging commands.</li><li><code>AGENTS.md</code>, <code>CLAUDE.md</code>, <code>.cursor/rules/jetpack.mdc</code>, and <code>.agents/skills/*</code> — AI agent instructions and workflows (automatically excluded from OCI packaging).</li></ul><h3 id="validate-manifest-path" tabindex="-1"><code>--validate-manifest &lt;path&gt;</code> <a class="header-anchor" href="#validate-manifest-path" aria-label="Permalink to &quot;`--validate-manifest &lt;path&gt;`&quot;">​</a></h3><p>Parses an <code>app.toml</code> file with <code>#[serde(deny_unknown_fields)]</code> and runs all semantic and security checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --validate-manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker/app.toml</span></span></code></pre></div><h3 id="install-local-app-source-dir" tabindex="-1"><code>--install-local-app &lt;source_dir&gt;</code> <a class="header-anchor" href="#install-local-app-source-dir" aria-label="Permalink to &quot;`--install-local-app &lt;source_dir&gt;`&quot;">​</a></h3><p>Validates, packages, and installs a local developer worker (plus any <code>ui/</code> bundle) directly into <code>&lt;root&gt;/blobs/sha256/</code> and <code>&lt;root&gt;/apps/&lt;app-id&gt;/&lt;version&gt;/</code> in unverified developer mode (<code>is_verified = false</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-local-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span></span></code></pre></div><ul><li>Blocks official <code>SignedAppCatalog</code> IDs (<code>APP_SPOOFING_DETECTED</code>).</li><li>Displays the app with an <code>UNVERIFIED / LOCAL DEV</code> badge in Control Center, automatically discovers <code>&lt;root&gt;/apps/&lt;app-id&gt;/&lt;version&gt;/ui/index.html</code> for <code>/apps/&lt;app-id&gt;/</code>, and restricts WebSocket origins to <code>127.0.0.1</code> / <code>localhost</code>.</li></ul><h3 id="package-app-source-dir-out-bundle-dir-oci-ref-ref" tabindex="-1"><code>--package-app &lt;source_dir&gt; --out &lt;bundle_dir&gt; [--oci-ref &lt;ref&gt;]</code> <a class="header-anchor" href="#package-app-source-dir-out-bundle-dir-oci-ref-ref" aria-label="Permalink to &quot;`--package-app &lt;source_dir&gt; --out &lt;bundle_dir&gt; [--oci-ref &lt;ref&gt;]`&quot;">​</a></h3><p>Packages a validated worker directory (including optional <code>ui/</code> static assets served dynamically at <code>/apps/&lt;app-id&gt;/</code>) into an ORAS-compatible <strong>OCI Image Layout v1.0.0</strong> directory (<code>index.json</code> with <code>org.opencontainers.image.ref.name</code>) and prints <code>manifest_sha256</code>, the <code>oras cp --from-oci-layout</code> push command, <code>oras manifest fetch --descriptor</code> digest check, and a <code>CatalogAppEntry</code> JSON snippet:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --package-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workers/my-ocr-worker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dist/my-ocr-worker-oci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oci-ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/your-org/my-ocr-worker:0.1.0</span></span></code></pre></div><p>Automatically strips <code>*.key</code>, <code>*.pem</code>, <code>*.secret</code>, <code>jetpack-root-signing*</code>, <code>node_modules/</code>, <code>target/</code>, <code>.git/</code>, <code>.venv/</code>, <code>__pycache__/</code>, and symlinks so build caches, secrets, and unsafe links cannot leak into published layers.</p><h2 id="catalog-operator-commands" tabindex="-1">Catalog Operator Commands <a class="header-anchor" href="#catalog-operator-commands" aria-label="Permalink to &quot;Catalog Operator Commands&quot;">​</a></h2><h3 id="generate-catalog-keypair-out-priv-path" tabindex="-1"><code>--generate-catalog-keypair --out-priv &lt;path&gt;</code> <a class="header-anchor" href="#generate-catalog-keypair-out-priv-path" aria-label="Permalink to &quot;`--generate-catalog-keypair --out-priv &lt;path&gt;`&quot;">​</a></h3><p>Generates an <code>Ed25519</code> root keypair using <code>OsRng</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --generate-catalog-keypair</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out-priv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.secrets/jetpack-root-signing.key</span></span></code></pre></div><ul><li>Writes the 32-byte seed (64 lowercase hex characters) atomically (<code>create_new(true)</code>) with mode <code>0600</code> on Unix.</li><li>Prints only the public key hex and the Rust <code>CATALOG_VERIFY_PUBKEY</code> literal to stdout.</li></ul><h3 id="sign-catalog-catalog-json-path-key-priv-key-path" tabindex="-1"><code>--sign-catalog &lt;catalog_json_path&gt; [--key &lt;priv_key_path&gt;]</code> <a class="header-anchor" href="#sign-catalog-catalog-json-path-key-priv-key-path" aria-label="Permalink to &quot;`--sign-catalog &lt;catalog_json_path&gt; [--key &lt;priv_key_path&gt;]`&quot;">​</a></h3><p>Canonicalizes <code>SignedAppCatalog</code>, signs it with <code>Ed25519</code> (reading <code>--key</code> or <code>JETPACK_SIGNING_KEY</code>), writes <code>ed25519_signature</code> atomically, and immediately re-verifies the file from disk:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jetpack-daemon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sign-catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crates/jetpack-daemon/assets/catalog.signed.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.secrets/jetpack-root-signing.key</span></span></code></pre></div><h2 id="runtime-inspection-diagnostic-flags" tabindex="-1">Runtime, Inspection &amp; Diagnostic Flags <a class="header-anchor" href="#runtime-inspection-diagnostic-flags" aria-label="Permalink to &quot;Runtime, Inspection &amp; Diagnostic Flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--version, -V</code></td><td style="text-align:left;">Print the compiled <code>jetpack-daemon</code> semantic version and exit cleanly.</td></tr><tr><td style="text-align:left;"><code>--headless</code></td><td style="text-align:left;">Run <code>jetpack-daemon</code> without a desktop system tray icon (CI / server).</td></tr><tr><td style="text-align:left;"><code>--seed-core-apps</code></td><td style="text-align:left;">Package and pre-install curated core workers from <code>examples/</code> (e.g., slim release bundle <code>examples/ffmpeg-media-converter</code>, excluding <code>.venv</code>, <code>__pycache__</code>, <code>tests</code>, and media files) into CAS and <code>&lt;root&gt;/apps/</code>.</td></tr><tr><td style="text-align:left;"><code>--export-diagnostics [--out &lt;path&gt;]</code></td><td style="text-align:left;">Collect a sanitized <code>.zip</code> diagnostic bundle (<code>diagnostics.json</code> + redacted <code>daemon.log</code> tail) and write it to <code>&lt;path&gt;</code> or <code>&lt;root&gt;/logs/jetpack-diagnostics-&lt;timestamp&gt;.zip</code>.</td></tr><tr><td style="text-align:left;"><code>--print-hardware-profile</code></td><td style="text-align:left;">Probe CPU topology, RAM/unified memory, and GPUs (<code>NVML</code>, <code>Vulkan</code>, <code>DX12</code>, <code>Metal</code>).</td></tr><tr><td style="text-align:left;"><code>--list-paired-clients</code></td><td style="text-align:left;">List approved origins and client UUIDs stored in <code>paired_clients.db</code>.</td></tr><tr><td style="text-align:left;"><code>--list-installed-apps</code></td><td style="text-align:left;">Scan <code>&lt;root&gt;/apps/</code> and print discovered manifests and versions.</td></tr><tr><td style="text-align:left;"><code>--register-uri-scheme</code></td><td style="text-align:left;">Register <code>jetpack://</code> and <code>corenode://</code> custom URL schemes in user space.</td></tr><tr><td style="text-align:left;"><code>--generate-test-pair-uri</code></td><td style="text-align:left;">Print a deterministic test <code>jetpack://pair</code> URI and SHA-256 fingerprint.</td></tr><tr><td style="text-align:left;"><code>--test-ws-client</code></td><td style="text-align:left;">Connect to a running daemon (<code>127.0.0.1:9470</code>) to verify PNA, handshake, and <code>system.echo</code> (supports <code>--send-json</code> and <code>--origin</code>).</td></tr><tr><td style="text-align:left;"><code>--ws-smoke-test</code></td><td style="text-align:left;">Run offline end-to-end WebSocket security and <code>hardware.get_profile</code> smoke test.</td></tr><tr><td style="text-align:left;"><code>--oci-smoke-test</code></td><td style="text-align:left;">Run offline OCI CAS, SHA-256 verification, and hardlink/APFS clone smoke test.</td></tr><tr><td style="text-align:left;"><code>--oci-remote-smoke-test &lt;ref&gt; [--expected-digest &lt;sha256:...&gt;]</code></td><td style="text-align:left;">Pull a live public OCI reference (such as <code>ghcr.io/...</code>), verify manifest + blob SHA-256 digests, and safely unpack into an isolated temporary CAS root.</td></tr><tr><td style="text-align:left;"><code>--python-smoke-test</code></td><td style="text-align:left;">Run offline hermetic <code>uv</code> + <code>python-build-standalone</code> provisioner smoke test.</td></tr><tr><td style="text-align:left;"><code>--sandbox-smoke-test</code></td><td style="text-align:left;">Run offline OS native kernel sandbox (<code>AppContainer</code> / <code>Seatbelt</code> / <code>bwrap+Landlock</code>) smoke test.</td></tr><tr><td style="text-align:left;"><code>--worker-ipc-smoke-test</code></td><td style="text-align:left;">Run offline sandboxed worker IPC, userspace proxy, and lifecycle cleanup smoke test.</td></tr><tr><td style="text-align:left;"><code>--full-e2e-smoke-test</code></td><td style="text-align:left;">Run the full end-to-end orchestrator, sandbox, GPU worker, and WebSocket integration test.</td></tr><tr><td style="text-align:left;"><code>--background</code></td><td style="text-align:left;">Hidden internal flag omitted from <code>--help</code>; passed by OS autostart entries (<code>LaunchAgents</code>, <code>HKCU\\...\\Run</code>, XDG <code>.desktop</code>) to suppress auto-opening the Control Center window at OS login.</td></tr><tr><td style="text-align:left;"><code>--cleanup-old-binary &lt;path&gt;</code></td><td style="text-align:left;">Hidden internal post-update flag spawned by the self-updater; validates a <code>.old</code> suffix and removes the previous binary or <code>.app.old</code> bundle asynchronously (<code>10 × 200ms</code> retries).</td></tr></tbody></table>',50)])])}const g=t(i,[["render",s]]);export{k as __pageData,g as default};
